(()=>{
const examples={
 instructions:{title:'Add an experiment checklist',purpose:'Make planning and submission checks explicit before the agent spends its experiment budget.',before:'No extra campaign instructions.',after:'Read the task files first. Keep a validated model on disk from the start. Check every batch before running it.',file:'instructions.md',actual:'Actual round 1 edit'},
 skills:{title:'Package a reusable review procedure',purpose:'Give the agent a procedure it can consult when a particular kind of work needs checking.',before:'The agent invents its review procedure each time.',after:'A skill explains how to inspect an output, test its format, and report unresolved issues.',file:'skills/<skill-name>/SKILL.md'},
 tools:{title:'Add a small validation helper',purpose:'Turn a repetitive check into code the agent can run through its existing tools.',before:'The agent checks an input file manually.',after:'A helper script checks required columns and duplicate rows, then prints the problems it found.',file:'A Python or JavaScript helper in the harness bundle'},
 memory:{title:'Keep a useful working record',purpose:'Help the agent recover its plan when the conversation grows long, using information from its own run.',before:'Decisions and remaining work are scattered through the conversation.',after:'Instructions tell the agent to maintain a short note of completed work, results, and the next action.',file:'Instructions or helpers that manage task-local notes'},
 hooks:{title:'Audit before stopping',purpose:'Use a runtime event instead of relying on the agent to remember a final check.',before:'The agent stops as soon as its model is accepted.',after:'Once, when a model is delivered and time remains, a stop hook asks for a held-out check against one different alternative.',file:'hooks.json → tools/stop_audit.py',actual:'Actual round 3 edit (selected)'}
};
const phases=[
 ['Read the evidence','The first round starts with public task instructions. Later rounds also use scores and traces from this experiment.','Read public task requirements and previous results.'],
 ['Propose a concrete edit','The proposer changes a copy of the retained harness. The highlighted component shows where the edit goes.','A candidate is a real file change, with a reason to test it.'],
 ['Check the boundaries','An automatic gate checks the format, scans for copied task text, secrets and answers, and runs the new code offline. A critic then checks for task-specific hardcoding. A rejected proposal never reaches the trials.','Passing checks permits testing; it is not a performance result.'],
 ['Test the candidate','Fresh task agents use the edited harness. One screening trial per task comes first; two more per task follow unless the candidate clearly fails.','The dots represent trial slots, not wins.'],
 ['Decide, then learn','If the measured scores clear the keep rule, the edit becomes part of the next parent. Otherwise the parent stays. Either way, the results inform the next proposal.','Keep the candidate only if it earns its place; retain all evidence.']
];
const root=document.getElementById('harness-demo'),play=document.getElementById('demo-play');let phase=0,playing=false,timer=null,visible=false;const reduced=matchMedia('(prefers-reduced-motion: reduce)');
function render(){root.dataset.phase=phase;root.querySelectorAll('[data-phase]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.phase)===phase)));document.getElementById('demo-counter').textContent=`${phase+1} / 5`;document.getElementById('demo-title').textContent=phases[phase][0];document.getElementById('demo-description').textContent=phases[phase][1];document.getElementById('proposal-status').textContent=phases[phase][2];}
function stopTimer(){clearInterval(timer);timer=null;}
function clock(){stopTimer();if(playing&&visible&&!document.hidden)timer=setInterval(()=>{phase=(phase+1)%5;render();},4200);}
function setPlaying(value){playing=value;root.classList.toggle('is-playing',value);play.textContent=value?'Pause':'Play';play.setAttribute('aria-pressed',String(value));clock();}
play.addEventListener('click',()=>setPlaying(!playing));document.getElementById('demo-next').addEventListener('click',()=>{setPlaying(false);phase=(phase+1)%5;render();});document.getElementById('demo-reset').addEventListener('click',()=>{setPlaying(false);phase=0;render();});root.querySelectorAll('.demo-stages button').forEach(b=>b.addEventListener('click',()=>{setPlaying(false);phase=Number(b.dataset.phase);render();}));root.querySelectorAll('[data-component]').forEach(b=>b.addEventListener('click',()=>{setPlaying(false);const e=examples[b.dataset.component];root.querySelectorAll('[data-component]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)));for(const [id,value] of Object.entries({'edit-title':e.title,'edit-purpose':e.purpose,'edit-before':e.before,'edit-after':e.after,'edit-file':e.file,'example-kind':e.actual||'Illustrative example'}))document.getElementById(id).textContent=value;document.getElementById('example-kind').classList.toggle('illustrative',!e.actual);phase=1;render();}));
let firstView=true;new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;if(visible&&firstView){firstView=false;setPlaying(!reduced.matches);}else clock();},{threshold:.25}).observe(root);document.addEventListener('visibilitychange',clock);reduced.addEventListener('change',()=>{if(reduced.matches)setPlaying(false);});render();
})();
